from ta_a2a.auto2analysis import check_logs_with_au2anlysis
from ta_a2a.auto2analysis import check_multi_log
from ta_a2a.auto2analysis import wireshark_filter_msg


class ta_a2a(object):
    """
    https://gitlabe1.ext.net.nokia.com/devhz/a2a/wikis/home
    """
    def check_log_with_au2anlysis(
            self,
            ini_path,
            log_need_to_check,
            ini_modify=None,
            save_log_directory=None):
        """This keyword used for calling Au2Analysis.exe to analysis kinds of logs,
           such as UDP log, Trace log, TM500 log and TtiTrace log.

        | log type explain:
        |     u   UDP log
        |     t   Trace log
        |     m   TM500 log
        |     i   TtiTrace log
        |     p   TM500 Protocol log, iphy log
        |     w   Wireshark log

        :param ini_path:                      ini file path
        :param log_need_to_check:             should be "u t m i p w"
        :param ini_modify:                    default as None, could be string or list
        :param save_log_directory:            could be "save_log_directory=/tmp/A2A/Logfolder"

        ::

            # For trace, tm500, ttitrace and tm500 protocol log check
            check_log_with_au2anlysis    /tmp/A2A/A2A.ini    tmip    save_log_directory=/tmp/A2A/log

            # For udp and wireshark log check
            check_log_with_au2anlysis    /tmp/A2A/A2A.ini    uw      UDPLOG_TAG_1: UDPlog*.log    save_log_directory=/tmp/A2A/log

            # For udp and wireshark log check with parameter change in ini file
            ${modify_list}    create list    LOGDIR: /tmp/A2A    UDPLOG_TAG_1: UDPlog*.log
            check_log_with_au2anlysis     /tmp/A2A/A2A.ini    uw    ${modify_list}   save_log_directory=/tmp/A2A/log
        """
        check_logs_with_au2anlysis(
            ini_path,
            log_need_to_check,
            ini_modify,
            save_log_directory)

    def check_multi_logs(self, ini_path, log_save_path):
        '''check wireshark, protocl and iphy logs
        :param ini_path: ini file path
        :param log_save_path: need to test log path, it's a folder
        '''
        return check_multi_log(ini_path, log_save_path)

    def wireshark_filter_msg(self, input_file, output_file, filter_msg):
        '''filter wireshark log by specific keyword
        :param input_file: source txt file path
        :param output_file: target txt file path
        :param filter_msg: need to filter frame message
        '''
        return wireshark_filter_msg(input_file, output_file, filter_msg)
